CREATE OR REPLACE FUNCTION public.normalize_athlete_names() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.nome := initcap(lower(btrim(NEW.nome))); NEW.cognome := initcap(lower(btrim(NEW.cognome))); RETURN NEW; END $$;
CREATE TRIGGER normalize_athlete_names_before_write BEFORE INSERT OR UPDATE OF nome, cognome ON public.atleti FOR EACH ROW EXECUTE FUNCTION public.normalize_athlete_names();
CREATE OR REPLACE FUNCTION public.normalize_registration_names_and_status() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.snapshot_nome IS NOT NULL THEN NEW.snapshot_nome := initcap(lower(btrim(NEW.snapshot_nome))); END IF; IF NEW.snapshot_cognome IS NOT NULL THEN NEW.snapshot_cognome := initcap(lower(btrim(NEW.snapshot_cognome))); END IF; IF TG_OP = 'INSERT' AND auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(), 'admin') THEN NEW.stato := 'confermata'; END IF; RETURN NEW; END $$;
CREATE TRIGGER z_normalize_registration_before_write BEFORE INSERT OR UPDATE OF snapshot_nome, snapshot_cognome ON public.iscrizioni FOR EACH ROW EXECUTE FUNCTION public.normalize_registration_names_and_status();